/* ===== Trò chuyện theo khoảng cách (D-041): lõi phía khách (không DOM, không three) =====
   Sổ tin của phiên (tin mình chờ hồi âm, tin người khác, chưa đọc, giới hạn tần suất) và danh sách người ở gần có trễ hai ngưỡng.
   Mọi con số truyền vào từ multiParams.chat; phần DOM (chat.ts) chỉ vẽ theo những gì ở đây trả ra. */
import type { ChatWhy, Kind } from './protocol';

/* pending: chờ chatAck; ok: đã tới n ≥ 1 người; alone: không ai ở gần (n = 0); fail: quá hạn / mất kết nối / không giữ chỗ / rỗng; rate: gửi quá nhanh; bad: có từ tục */
export type ChState = 'pending' | 'ok' | 'alone' | 'fail' | 'rate' | 'bad';
// key: số thứ tự duy nhất trong phiên (khóa DOM); id: số ghép chatAck (chỉ tin mình, tin người khác 0); tin mình: k 'fly', slot −1, name '' (bên vẽ dựa vào mine); at: giờ thêm (ms)
export interface ChMsg { key: number; id: number; mine: boolean; k: Kind; slot: number; name: string; text: string; at: number; state: ChState; n: number }
// Người khác cùng phòng: vị trí nội suy (m)
export interface ChPeer { k: Kind; slot: number; name: string; x: number; y: number; z: number }

/* Khóa một người: loại + slot (ba nhóm slot riêng nên cùng slot khác loại là hai người) */
export const chKey = (k: Kind, slot: number): string => k + ':' + slot;

/* Người ở gần (trễ hai ngưỡng): vào khi d ≤ nearIn, đã có trong prev thì ở lại tới d ≤ radius; khoảng cách 3D từ vị trí mình vừa gửi; giữ thứ tự peers */
export function chNear(self: { x: number; y: number; z: number } | null, peers: ChPeer[], prev: ReadonlySet<string>, nearIn: number, radius: number): ChPeer[] {
  if (!self) return [];
  const out: ChPeer[] = [];
  for (const p of peers) {
    const dx = p.x - self.x, dy = p.y - self.y, dz = p.z - self.z;
    const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
    if (d <= nearIn || (d <= radius && prev.has(chKey(p.k, p.slot)))) out.push(p);
  }
  return out;
}

/* ===== Sổ tin của một phiên (chỉ trong bộ nhớ; phiên mới thì clear) ===== */
export class ChLog {
  readonly list: ChMsg[] = [];
  unread = 0;
  private nextKey = 1;    // không đặt lại khi clear: khóa DOM không lặp
  private nextId = 1;
  private sent: number[] = [];   // giờ các tin mình đã gửi trong rateWinMs gần nhất (cùng cách tính với máy chủ)

  constructor(private historyMax: number, private ackMs: number, private ratePerWin: number, private rateWinMs: number) {}

  /* Hạn mức phía khách: < ratePerWin tin trong cửa sổ trượt rateWinMs (máy chủ cũng chặn, đây chỉ để khỏi gửi tin chắc chắn bị từ chối) */
  canSend(now: number): boolean {
    this.sent = this.sent.filter(t => now - t < this.rateWinMs);
    return this.sent.length < this.ratePerWin;
  }

  addMine(text: string, now: number): ChMsg {
    const m: ChMsg = { key: this.nextKey++, id: this.nextId++, mine: true, k: 'fly', slot: -1, name: '', text, at: now, state: 'pending', n: 0 };
    this.list.push(m); this.sent.push(now);
    return m;
  }

  addTheirs(k: Kind, slot: number, name: string, text: string, now: number, panelOpen: boolean): ChMsg {
    const m: ChMsg = { key: this.nextKey++, id: 0, mine: false, k, slot, name, text, at: now, state: 'ok', n: 0 };
    this.list.push(m);
    if (!panelOpen) this.unread++;
    return m;
  }

  /* Hồi âm: chỉ đổi tin mình đang pending (hồi âm trễ sau khi đã fail không đổi lại); trả tin vừa đổi, null nếu không có */
  ack(id: number, n: number | undefined, why: ChatWhy | undefined): ChMsg | null {
    const m = this.list.find(x => x.mine && x.id === id && x.state === 'pending');
    if (!m) return null;
    if (typeof n === 'number' && n >= 1) { m.state = 'ok'; m.n = n; }
    else if (n === 0) m.state = 'alone';
    else m.state = why === 'rate' ? 'rate' : why === 'bad' ? 'bad' : 'fail';
    return m;
  }

  /* Tin pending đã chờ ≥ ackMs thành fail; trả các tin vừa đổi */
  expire(now: number): ChMsg[] {
    const out: ChMsg[] = [];
    for (const m of this.list) if (m.state === 'pending' && now - m.at >= this.ackMs) { m.state = 'fail'; out.push(m); }
    return out;
  }

  /* Mất kết nối: mọi tin pending thành fail */
  failAll(): ChMsg[] {
    const out: ChMsg[] = [];
    for (const m of this.list) if (m.state === 'pending') { m.state = 'fail'; out.push(m); }
    return out;
  }

  /* Gỡ tin cũ nhất tới khi còn ≤ historyMax; trả tin bị gỡ (bên vẽ xóa phần tử DOM tương ứng) */
  trim(): ChMsg[] {
    return this.list.length > this.historyMax ? this.list.splice(0, this.list.length - this.historyMax) : [];
  }

  read(): void { this.unread = 0; }

  clear(): void { this.list.length = 0; this.unread = 0; this.sent = []; }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: nhãn tên nổi cạnh người chơi khác =====
   Một div cho mỗi slot bay, mỗi slot đi dạo và mỗi slot lái xe trong #exMpLabels (theo thứ tự đó). Dù: điểm đặt nhãn thấp hơn dù labelBelow m (tên nằm dưới cánh, không che dù);
   người đi dạo: cao hơn chân CONFIG.stroll.labelAbove m (trên đầu); xe: trên nóc, cao hơn mặt đường car.height + drive.remote.labelAbove m (xe máy: bike.body.height + bike.remote.labelAbove, trên mũ người lái). Ẩn khi sau camera hoặc slot chưa hiện; nhân vật của mình không có nhãn.
   Chỉ ghi DOM khi chữ đổi (tên + khoảng cách, làm tươi ≤ 5 lần/s) hoặc vị trí lệch quá 1 px. Không cấp phát mỗi khung (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import type { exRemotes } from './remote';
import type { stAvatars } from '../stroll/avatars';
import type { exDrivers } from './remoteDrive';

const M = CONFIG.explore.multi, NW = M.stroll.slots, ND = M.drive.slots, CAR_TOP = CONFIG.drive.car.height + CONFIG.drive.remote.labelAbove, BIKE_TOP = CONFIG.bike.body.height + CONFIG.bike.remote.labelAbove;
interface Lab { el: HTMLElement; txt: string; x: number; y: number; shown: boolean; tMs: number }
let labs: Lab[] | null = null;   // M.slots nhãn dù, NW nhãn người đi dạo rồi ND nhãn xe
const _v = new THREE.Vector3();

function init(): Lab[] | null {
  const box = document.getElementById('exMpLabels');
  if (!box) return null;
  return Array.from({ length: M.slots + NW + ND }, () => {
    const el = document.createElement('div'); el.className = 'ex-mp-label'; el.hidden = true; box.appendChild(el);
    return { el, txt: '', x: -1e9, y: -1e9, shown: false, tMs: -1e9 };
  });
}

// Khoảng cách làm tròn: < 1000 m ghi "NNN m", còn lại "N.N km"
const dist = (d: number) => d < 1000 ? `${Math.round(d)} m` : `${(d / 1000).toFixed(1)} km`;

/* Đặt một nhãn tại điểm (x, y, z) với tên name; trả true nếu hiện */
function place(L: Lab, camera: THREE.Camera, x: number, y: number, z: number, name: string, nowMs: number, w: number, h: number): boolean {
  _v.set(x, y, z).applyMatrix4(camera.matrixWorldInverse);
  if (-_v.z <= 0.1) return false;   // sau camera
  _v.applyMatrix4(camera.projectionMatrix);
  const px = (_v.x * 0.5 + 0.5) * w, py = (-_v.y * 0.5 + 0.5) * h;
  if (px <= -80 || px >= w + 80 || py <= -40 || py >= h + 40) return false;
  if (nowMs - L.tMs >= 200) {
    L.tMs = nowMs;
    const txt = `${name} · ${dist(Math.hypot(x - camera.position.x, y - camera.position.y, z - camera.position.z))}`;
    if (txt !== L.txt) { L.txt = txt; L.el.textContent = txt; }
  }
  if (Math.abs(px - L.x) > 1 || Math.abs(py - L.y) > 1) { L.x = px; L.y = py; L.el.style.transform = `translate(${px.toFixed(0)}px,${py.toFixed(0)}px) translateX(-50%)`; }
  return true;
}

export function exLabelsUpdate(camera: THREE.Camera, remotes: typeof exRemotes, nowMs: number, walkers?: typeof stAvatars, drivers?: typeof exDrivers): void {
  if (!labs && !(labs = init())) return;
  const w = window.innerWidth, h = window.innerHeight;
  for (let i = 0; i < M.slots; i++) {
    const L = labs[i], st = remotes.slotState(i);
    const vis = !!st && place(L, camera, st.pos.x, st.pos.y - M.labelBelow, st.pos.z, remotes.name(i), nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
  for (let i = 0; i < NW; i++) {
    const L = labs[M.slots + i], st = walkers && i !== walkers.self ? walkers.slotState(i) : null, nm = st ? walkers!.name(i) : null;
    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + CONFIG.stroll.labelAbove, st.z, nm, nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
  for (let i = 0; i < ND; i++) {
    const L = labs[M.slots + NW + i], st = drivers ? drivers.slotState(i) : null, nm = st ? drivers!.name(i) : null;   // xe của mình không có trong exDrivers (slotState null)
    const vis = !!st && nm !== null && place(L, camera, st.x, st.y + (drivers!.vehOf?.(i) === 1 ? BIKE_TOP : CAR_TOP), st.z, nm, nowMs, w, h);
    if (vis !== L.shown) { L.shown = vis; L.el.hidden = !vis; }
  }
}

/* Ẩn hết nhãn (rời phòng) */
export function exLabelsClear(): void {
  if (!labs) return;
  for (const L of labs) { L.shown = false; L.el.hidden = true; L.x = L.y = -1e9; }
}
/* ===== Dù lượn, đi dạo và lái xe nhiều người: điều phối phía khách =====
   Nối MultiSession (kết nối, phiên) với exRemotes (dù người khác), stAvatars (người đi dạo khác), exDrivers (xe người khác), nhãn tên và danh sách người chơi.
   Cả ba loại thấy nhau; mỗi phiên chỉ giữ một loại chỗ (session.kind). drCars.group chỉ ở trong cảnh khi có xe (exDrivers.onCars), không thì 0 lệnh vẽ.
   Chỉ mở kết nối khi có người gọi begin(); ?test mà không có multi= thì url() rỗng nên không bao giờ mở WebSocket. */
import { scene, camera } from '../../core/renderer';
import { CONFIG } from '../../config';
import { t, onChange as onLang } from '../../i18n';
import { exConnect } from './client';
import { MultiSession } from './session';
import { exRemotes } from './remote';
import { exLabelsUpdate, exLabelsClear } from './labels';
import { ExIdle } from './idle';
import { stAvatars } from '../stroll/avatars';
import { stChar } from '../stroll/char';
import { exDrivers } from './remoteDrive';
import { drCars } from '../drive/cars';
import { exVehNorm, type Kind } from './protocol';
import type { GliderState } from '../flight';
import type { StState } from '../stroll/motion';
import type { DrState } from '../drive/motion';

const M = CONFIG.explore.multi;
let session: MultiSession | null = null;
let sentAt = -1e9;
let rosterKey = '';
let idle: ExIdle | null = null;
let idleTimer = 0, beatTimer = 0;   // setInterval kiểm tra rời máy + nhịp sống; chỉ chạy khi đang bay
let idleShown = '';                 // chữ đang hiện ở #exMpIdle ('' = ẩn): chỉ ghi DOM khi đổi

/* ===== Rời máy: đếm bằng setInterval (tab ẩn vẫn đếm), hết hạn thì trả slot và sang chế độ xem ===== */
/* ?idleMs / ?idleWarnMs chỉ đọc khi có ?test (để test rút ngắn) */
function idleParams(): [number, number] {
  const q = new URLSearchParams(location.search);
  if (!q.has('test')) return [M.idleMs, M.idleWarnMs];
  const n = (k: string, d: number) => { const v = Number(q.get(k)); return q.has(k) && v > 0 ? v : d; };
  return [n('idleMs', M.idleMs), n('idleWarnMs', M.idleWarnMs)];
}

function idleShow(text: string): void {
  const el = document.getElementById('exMpIdle');
  if (!el || text === idleShown) return;
  /* Lần đầu hiện thì đọc to một lần; các giây sau chỉ đổi chữ, không đọc lại */
  el.setAttribute('aria-live', idleShown === '' ? 'polite' : 'off');
  idleShown = text;
  el.textContent = text;
  el.hidden = text === '';
}

function idleTick(): void {
  if (!session || !idle || session.phase !== 'flying') return;
  const now = performance.now();
  const st = idle.tick(now);
  if (st === 'ok') idleShow('');
  else if (st === 'warn') idleShow(t('exMpIdle', { s: idle.remaining(now) }));
  else { idleShow(''); session.leave(); }   // leave → onChange → idleStop
}

function idleStart(): void {
  if (idleTimer || !session) return;   // đã chạy: không mở hai đồng hồ
  const [a, b] = idleParams();
  idle = new ExIdle(a, b); idle.reset(performance.now());
  idleShown = '';
  idleTimer = window.setInterval(idleTick, M.idleTickMs);
  beatTimer = window.setInterval(() => session?.heartbeat(), M.heartbeatMs);
}

function idleStop(): void {
  clearInterval(idleTimer); clearInterval(beatTimer);
  idleTimer = beatTimer = 0; idle = null;
  idleShow('');
}

/* Danh sách người chơi ở góc màn hình: đầu "Lái xe n/5 · Đi dạo n/5 · Bay n/5", rồi nhóm người lái (chấm thoi, tên kèm 🚗 / 🛵 theo loại xe), người đi dạo (chấm vuông) và người bay (chấm tròn),
   mỗi người một dòng có chấm màu theo slot; dòng của mình đậm. Dùng textContent */
function renderRoster(): void {
  const box = document.getElementById('exMpRoster');
  if (!box) return;
  const flyers = session ? session.flyers : [], walkers = session ? session.walkers : [], drivers = session ? session.drivers : [];
  const head = t('drRosterAll', { d: drivers.length, w: walkers.length, f: flyers.length });
  const kind = session ? session.kind : 'fly', mine = session ? session.mySlot : -1;
  const key = drivers.map(f => f.slot + ':' + exVehNorm(f.veh) + ':' + f.name).join('|') + '#' + walkers.map(f => f.slot + ':' + f.name).join('|') + '#' + flyers.map(f => f.slot + ':' + f.name).join('|') + '#' + kind + mine + '#' + head;
  if (key === rosterKey) return;
  rosterKey = key;
  box.hidden = !session || session.phase === 'solo';
  box.textContent = '';
  const h = document.createElement('div'); h.className = 'ex-mp-head'; h.textContent = head; box.appendChild(h);
  const group = (list: typeof flyers, k: 'fly' | 'walk' | 'drive') => {
    for (const f of list) {
      const row = document.createElement('div'); row.className = 'ex-mp-row' + (k === 'walk' ? ' walk' : k === 'drive' ? ' drive' : '') + (k === kind && f.slot === mine ? ' me' : '');
      const dot = document.createElement('i'); dot.style.background = M.colors[f.slot % M.colors.length];
      const nm = document.createElement('span'); nm.textContent = f.name;
      if (k === 'drive') { const ic = document.createElement('span'); ic.textContent = exVehIcon(f.veh); ic.setAttribute('aria-hidden', 'true'); row.append(dot, ic, nm); }   // biểu tượng tách khỏi tên (tên RTL không kéo lệch)
      else row.append(dot, nm);
      box.appendChild(row);
    }
  };
  group(drivers, 'drive'); group(walkers, 'walk'); group(flyers, 'fly');
}

/* Người đi dạo hiện cho cả người bay: dựng nhóm nhân vật (lười) lần đầu phòng có người đi dạo; mô hình có xương nạp khi slot đầu tiên hiện */
function stEnsureAvatars(): void {
  const mesh = stAvatars.build();
  if (!mesh.parent) scene.add(mesh);
}

/* Biểu tượng loại xe trong danh sách người lái (sảnh, góc màn hình): 🛵 xe máy, 🚗 ô tô (máy chủ cũ không gửi veh = ô tô) */
export const exVehIcon = (veh: unknown): string => exVehNorm(veh) === 1 ? '🛵' : '🚗';

/* Xe người lái hiện cho cả người bay và người đi dạo: gắn / gỡ nhóm ô tô và nhóm xe máy người khác theo số xe (không có xe thì không ở trong cảnh) */
exDrivers.onCars = (n: number, nb = 0): void => {
  const g = drCars.group, b = exDrivers.bikes;
  if (n > 0) { if (!g.parent) scene.add(g); } else if (g.parent) g.removeFromParent();
  if (nb > 0) { if (!b.parent) scene.add(b); } else if (b.parent) b.removeFromParent();
};

export const exMulti = {
  /* Địa chỉ máy chủ: có ?test thì ?multi= nếu có, không có thì rỗng (không mở mạng); không có ?test thì luôn là địa chỉ cấu hình (người ngoài không đổi được máy chủ qua URL) */
  url(): string {
    const q = new URLSearchParams(location.search);
    if (!q.has('test')) return M.url;
    return q.get('multi') ?? '';
  },
  get session(): MultiSession | null { return session; },
  onChange: (() => {}) as () => void,   // móc cho giao diện sảnh (Task 6) và test

  /* Mở phiên loại kind ('fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe); veh (chỉ 'drive'): 0 ô tô, 1 xe máy (chung 5 chỗ lái với ô tô).
     onReady gọi một lần khi có thông tin đầu tiên (sảnh hoặc ngoại tuyến). Trả false nếu không có địa chỉ */
  begin(onReady: () => void, kind: Kind = 'fly', veh = 0): boolean {
    const url = exMulti.url();
    if (!url || session) return false;
    const s = session = new MultiSession(() => exConnect(url, M.connectTimeoutMs), undefined, kind);
    if (kind === 'drive') s.veh = veh === 1 ? 1 : 0;
    if (kind === 'walk' || s.veh === 1) s.ch = stChar.get();   // nhân vật đã chọn lần trước (chung Đi dạo và xe máy); sảnh đổi thì ghi lại (lobby.ts)
    let ready = false;
    s.onPos = f => exRemotes.onPos(f, performance.now());
    s.onWalkPos = w => stAvatars.onPos(w, performance.now());
    s.peersDrive = d => exDrivers.onPos(d, performance.now());
    s.onChange = () => {
      exRemotes.sync(s.flyers, s.kind === 'fly' ? s.mySlot : -1);   // slot đi dạo và slot bay là hai nhóm: số slot của mình chỉ loại trừ trong nhóm của mình
      if (s.walkers.length || stAvatars.mesh) { stEnsureAvatars(); stAvatars.sync(s.walkers, s.kind === 'walk' ? s.mySlot : -1); }
      exDrivers.sync(s.drivers, s.kind === 'drive' ? s.mySlot : -1);
      if (s.phase === 'solo') exLabelsClear();
      renderRoster();
      if (s.phase === 'flying') idleStart(); else idleStop();
      exMulti.onChange();
      if (!ready) { ready = true; onReady(); }
    };
    s.open();
    return true;
  },

  /* Đóng phiên (Quay lại / Esc ở sảnh, hoặc chọn Bay một mình khi có máy chủ): đóng WebSocket, ẩn dù người khác, nhãn, danh sách; begin() mở lại được */
  end(): void {
    if (!session) return;
    session.dispose(); session = null;
    exMulti.onChange = () => {};
    idleStop(); exRemotes.clear(); stAvatars.clear(); exDrivers.clear(); exLabelsClear();
    rosterKey = ''; renderRoster();
  },

  /* Mỗi khung (bay, đi dạo, lái xe hoặc xem): dù người khác, người đi dạo khác, xe người khác, nhãn; đang bay thì gửi vị trí sendHz lần/s (state = null: không gửi) */
  update(dt: number, nowMs: number, state: GliderState | null): void {
    if (!session) return;
    exRemotes.update(nowMs);
    if (stAvatars.mesh) stAvatars.update(nowMs);   // người đi dạo khác, kể cả khi mình bay dù
    exDrivers.update(nowMs, dt);   // xe người khác, kể cả khi mình bay dù hoặc đi dạo
    exLabelsUpdate(camera, exRemotes, nowMs, stAvatars, exDrivers);
    if (state && session.kind === 'fly' && session.phase === 'flying' && nowMs - sentAt >= 1000 / M.sendHz) {
      sentAt = nowMs;
      const p = state.pos, r = (v: number) => Math.round(v * 10) / 10, a = (v: number) => Math.round(v * 1000) / 1000;
      session.sendPos(r(p.x), r(p.y), r(p.z), a(state.yaw), a(state.bank), Math.round(nowMs));
    }
  },

  /* Mỗi khung khi đi dạo có chỗ: gửi vị trí + dáng sendHz lần/s (s = null: không gửi) */
  updateWalk(nowMs: number, s: StState | null): void {
    if (!session || !s || session.kind !== 'walk' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendWalk(r(s.x), r(s.y), r(s.z), a(s.yaw), s.pose, Math.round(nowMs));
  },

  /* Mỗi khung khi lái xe có chỗ: gửi vị trí + vận tốc + góc lái sendHz lần/s (s = null: không gửi). Cả lúc đang sơ tán khỏi nhịp quay Cầu sông Hàn.
     st: giá trị của trường st, mặc định góc lái ô tô; xe máy truyền bkLeanToWire(độ nghiêng) */
  updateDrive(nowMs: number, s: DrState | null, st?: number): void {
    if (!session || !s || session.kind !== 'drive' || session.phase !== 'flying' || nowMs - sentAt < 1000 / M.sendHz) return;
    sentAt = nowMs;
    const r = (v: number) => Math.round(v * 100) / 100, a = (v: number) => Math.round(v * 1000) / 1000;
    session.sendDrive({ x: r(s.x), y: r(s.y), z: r(s.z), yaw: a(s.yaw), v: r(s.v), st: a(st ?? s.steer), ts: Math.round(nowMs) });
  },

  /* Người chơi vừa bấm phím điều khiển: đếm lại thời gian rời máy */
  activity(): void {
    if (!idle) return;
    idle.activity(performance.now());
    idleShow('');
  },

  /* Trạng thái dù đang xem (khi hết chỗ, Task 6); null nếu không xem ai */
  watchState(): GliderState | null {
    return session && session.kind === 'fly' && session.phase === 'watching' ? exRemotes.slotState(session.watched) : null;
  },

  /* Trạng thái người đi dạo đang xem (hết chỗ đi dạo); null nếu không xem ai */
  watchWalker(): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    return session && session.kind === 'walk' && session.phase === 'watching' && session.watched >= 0 ? stAvatars.slotState(session.watched) : null;
  },

  /* Trạng thái xe đang xem (hết chỗ lái); null nếu không xem ai hoặc xe chưa có mẫu */
  watchDriver(): { x: number; y: number; z: number; yaw: number; v: number } | null {
    return session && session.kind === 'drive' && session.phase === 'watching' && session.watched >= 0 ? exDrivers.slotState(session.watched) : null;
  }
};

