content.content:
/* ===== Dù lượn, đi dạo và lái xe nhiều người: máy trạng thái phiên (không DOM, không three) =====
   Một phiên thuộc một loại (kind): 'fly' giành chỗ bay, 'walk' giành chỗ đi dạo, 'drive' giành chỗ lái xe. Ba nhóm 5 slot riêng; peers là nhóm cùng loại với mình
   (dùng cho đầy chỗ, chọn người xem, lời mời). Phase 'flying' nghĩa là "đang giữ chỗ" cho mọi loại (đi dạo, lái xe cũng vậy). */
import type { ChatWhy, Flyer, Kind, ServerMsg } from './protocol';
import type { Transport } from './client';
import { multiParams } from './params';

export type Phase = 'connecting' | 'lobby' | 'flying' | 'watching' | 'solo';
export type Notice = '' | 'offline' | 'lost' | 'late' | 'nameBad' | 'released';

const KINDS: readonly unknown[] = ['fly', 'walk', 'drive'];
const fin = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);

export class MultiSession {
  phase: Phase = 'connecting';
  flyers: Flyer[] = [];
  walkers: Flyer[] = [];   // người đi dạo (lobby.walkers); máy chủ cũ không gửi
  drivers: Flyer[] = [];   // người lái xe (lobby.drivers); máy chủ cũ không gửi
  mySlot = -1;
  watched = -1;       // slot đang xem (trong nhóm cùng loại), -1 = không ai
  invite = false;     // đang xem và còn chỗ trống
  notice: Notice = '';
  name = '';
  ch = 0;             // nhân vật mình chọn (0 nam, 1 nữ); gửi kèm join kind 'walk' và join xe máy (sảnh và lời mời đều qua join())
  veh = 0;            // loại xe của phiên 'drive': 0 ô tô (gói join như khách cũ), 1 xe máy (join kèm veh + ch; máy chủ phải vọng veh trong joined)
  onChange: () => void = () => {};
  onPos: (f: number[][]) => void = () => {};
  onWalkPos: (w: number[][]) => void = () => {};
  peersDrive: (d: number[][]) => void = () => {};   // nhóm d của gói pos (mẫu onWalkPos): mỗi phần tử [slot, x, y, z, yaw, v, st, giờ gửi]
  chatOk = false;     // D-041: lobby gần nhất có chat === 1 (máy chủ cũ không có ⇒ ẩn chat); mất kết nối / máy chủ cũ ⇒ false
  onChat: (m: { k: Kind; slot: number; name: string; text: string }) => void = () => {};   // tin người khác ở gần; không gọi onChange
  onChatAck: (m: { id: number; n?: number; why?: ChatWhy }) => void = () => {};   // hồi âm tin mình; không gọi onChange
  private t: Transport | null = null;
  private disposed = false;
  private first = true; // chưa nhận lobby nào

  constructor(private connect: () => Promise<Transport>, private pick: (n: number) => number = n => Math.floor(Math.random() * n), readonly kind: Kind = 'fly') {}

  /* Danh sách cùng loại với mình */
  get peers(): Flyer[] { return this.kind === 'walk' ? this.walkers : this.kind === 'drive' ? this.drivers : this.flyers; }

  /* Số chỗ của nhóm cùng loại */
  private get cap(): number { return this.kind === 'walk' ? multiParams.stroll.slots : this.kind === 'drive' ? multiParams.drive.slots : multiParams.slots; }

  open(): void {
    this.connect().then(t => {
      if (this.disposed) { t.close(); return; }
      this.t = t;
      t.onMessage = m => this.recv(m);
      t.onClose = () => this.lost();
    }, () => {
      if (this.disposed) return;
      this.phase = 'solo'; this.notice = 'offline'; this.onChange();
    });
  }

  /* Người lái chỉ xin chỗ sau khi lobby đầu đã có drivers: máy chủ cũ (main trước D-034) coi join kind 'drive' là join bay và cho chiếm một chỗ bay */
  join(name: string): void {
    this.name = name; this.notice = '';
    if (this.kind === 'drive' && this.first) return;
  drive: {               // chế độ lái xe (D-034): nhóm slot thứ ba; số chép tay vì file này không import gì, tests/drive-unit/params.test.ts giữ khớp mạng đường và CONFIG.drive
    slots: 5,            // số chỗ lái cùng lúc, tách khỏi 5 chỗ bay và 5 chỗ đi dạo (theo thiết kế)
    bounds: { x0: -1950, x1: 1530, z0: -3670, z1: 1450 }, // m — khung kẹp vị trí người lái: drBounds(mạng đường) (x −1900..1480, z −3620..1400) nới 50 m mỗi phía
    yMin: -16.6,         // m — cao độ thấp nhất: đáy hầm −14,6 trừ 2 m
    yMax: 33.6,          // m — cao độ cao nhất: đỉnh mặt cầu 31,6 cộng 2 m
    vMax: 30,            // m/s — tốc độ có dấu lớn nhất máy chủ nhận: 100 km/h (27,78 m/s) cộng dư nhỏ (ước lượng)
    steerMax: 0.56       // rad — góc lái lớn nhất máy chủ nhận: asin(2,075 / 4,05) ≈ 0,538 cộng dư nhỏ (ước lượng)
  },
  chat: {                // trò chuyện theo khoảng cách (D-041): máy chủ chỉ giao tin tới người giữ chỗ ở gần người gửi
    radius: 150,         // m — khoảng cách 3D tối đa giữa hai pos để nhận tin, tính cả biên (ước lượng)
    nearIn: 140,         // m — khách báo "ở gần" khi d ≤ nearIn, thôi báo khi d > radius (trễ hai ngưỡng, chống nhấp nháy) (ước lượng)
    textMax: 200,        // code point tối đa của một tin sau khi làm sạch (ước lượng)
    linesMax: 4,         // số dòng tối đa của một tin, phần sau nối bằng khoảng trắng (ước lượng)
    marksMax: 4,         // dấu chồng (\p{M}) liên tiếp tối đa, dài hơn thì dồn còn chừng này (ước lượng)
    msgBytes: 1024,      // độ dài tối đa của gói chat nhận từ khách, đơn vị UTF-16 của chuỗi JSON; gói khác vẫn theo maxMsgBytes (ước lượng)
    ratePerWin: 5,       // số tin tối đa một kết nối được gửi trong rateWinMs (ước lượng)
    rateWinMs: 10000,    // ms — cửa sổ trượt tính tần suất gửi tin (ước lượng)
    ackMs: 4000,         // ms — khách chờ hồi âm chatAck, quá thì báo "Chưa gửi được" (ước lượng)
    nearTickMs: 500,     // ms — chu kỳ khách tính lại danh sách người ở gần (setInterval) (ước lượng)
