/* Bong bóng: đáy cách đỉnh nhãn 4 px, giữa theo nhãn */
const bubPos = (L: Lab): void => { L.bub!.style.transform = `translate(${L.x.toFixed(0)}px,${(L.y - 4).toFixed(0)}px) translate(-50%,-100%)`; };

