function bubStep(L: Lab, vis: boolean, nowMs: number): void {
  const on = vis && nowMs < L.bUntil;
  if (nowMs >= L.bUntil) L.bUntil = 0;
  if (on !== L.bShown) { L.bShown = on; L.bub!.hidden = !on; if (on) bubPos(L); }
}

